<script setup lang="ts">import {ref,computed,watch} from 'vue';import type {Workspace} from '../stores/workspace';import type {ReconciliationDetail} from '../types/domain';import {create,detail} from '../api/reconciliations';import {useAction} from '../hooks/useAction';import {num,short} from '../utils/format';import {RECONCILE_STATUSES,PAIR_STATUSES,MATCH_STATUSES} from '../constants/enums';import Heading from '../components/common/Heading.vue';import Notice from '../components/common/Notice.vue';import Empty from '../components/common/Empty.vue';import ReconcilePlot from '../components/ReconcilePlot.vue';
const props=defineProps<{data:Workspace;canWrite:boolean;refresh:()=>Promise<void>}>();const{busy,error,notice,act}=useAction();
const name=ref('复测换号·新对账'),lsid=ref(''),lgid=ref(''),rsid=ref(''),rgid=ref(''),threshold=ref(0.5);
const lsurvey=computed(()=>props.data.surveys.find(s=>s.id===lsid.value)||props.data.surveys[0]),rsurvey=computed(()=>props.data.surveys.find(s=>s.id===rsid.value)||props.data.surveys[1]||props.data.surveys[0]);
watch(()=>lsurvey.value?.id,v=>{if(v)lgid.value=lsurvey.value.groups[0]?.group_id||''},{immediate:true});watch(()=>rsurvey.value?.id,v=>{if(v)rgid.value=rsurvey.value.groups[0]?.group_id||''},{immediate:true});
const id=ref(''),tab=ref('pairs'),full=ref<ReconciliationDetail|null>(null);
const rec=computed(()=>props.data.reconciliations.find(r=>r.id===id.value)||props.data.reconciliations[0]);
watch(()=>rec.value?.id,()=>{if(rec.value&&id.value!==rec.value.id)id.value=rec.value.id},{immediate:true});
watch([()=>rec.value?.id,()=>rec.value?.status],async()=>{if(rec.value?.status==='completed'&&full.value?.id!==rec.value.id)full.value=await detail(rec.value.id);if(rec.value?.status!=='completed')full.value=null},{immediate:true});
const result=computed(()=>full.value?.id===rec.value?.id?full.value.result:null);
const shownPairs=computed(()=>result.value?result.value.pairs.slice(0,2000):[]);
function submit(){void act(async()=>{const r=await create({name:name.value,left:{survey_id:lsurvey.value.id,group_id:lgid.value},right:{survey_id:rsurvey.value.id,group_id:rgid.value},threshold_m:Number(threshold.value)});await props.refresh();id.value=r.id},'对账已冻结双方来源与阈值，提交后台计算')}
</script>
<template><Heading index="07 / RECONCILIATION" title="两点组对账，不抢占不遗漏。" detail="给定距离上限，每点最多配一次：先配对数最多，再总平方距离最小。列出能出现在任一最优方案中的全部配对，区分必然配对、归属歧义与始终未配点；重合坐标按原始编号各占名额。超过10秒整份拒绝。"/>
<section v-if="canWrite" class="form-section"><h2>冻结两点组对账</h2><p>双方来源与阈值冻结进快照，只读原始测组、不回写；每组1至300条，重合坐标不去重。</p><form class="form-grid" @submit.prevent="submit"><label>对账名称<input aria-label="对账名称" required v-model="name"/></label><label>距离上限 / 米<input aria-label="距离上限" type="number" min="0.000001" max="10000000000" step="any" required v-model="threshold"/></label><label>左侧测组<select aria-label="左侧测组" v-model="lsid"><option v-for="s in data.surveys" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>左侧点组<select aria-label="左侧点组" v-model="lgid"><option v-for="g in lsurvey?.groups" :key="g.group_id" :value="g.group_id">{{g.group_id}} {{g.name}} · {{g.points.length}}条</option></select></label><label>右侧测组<select aria-label="右侧测组" v-model="rsid"><option v-for="s in data.surveys" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>右侧点组<select aria-label="右侧点组" v-model="rgid"><option v-for="g in rsurvey?.groups" :key="g.group_id" :value="g.group_id">{{g.group_id}} {{g.name}} · {{g.points.length}}条</option></select></label><button class="primary" :disabled="busy||!data.surveys.length">冻结来源并提交对账</button></form><Notice :error="error" :notice="notice"/></section>
<Empty v-if="!data.reconciliations.length">先冻结一份两点组对账：选择左右测组点组与距离上限，后台按字典序最优配对。</Empty>
<template v-else><label class="selector">选择对账<select aria-label="选择对账" v-model="id"><option v-for="r in data.reconciliations" :key="r.id" :value="r.id">{{r.name}} · {{RECONCILE_STATUSES[r.status]}} · {{short(r.id)}}</option></select></label>
<article v-if="rec" class="evidence-section"><div class="result-meta"><span class="status" :class="rec.status">{{RECONCILE_STATUSES[rec.status]}}</span><span>阈值 {{rec.threshold_m}} m</span><span>{{data.surveys.find(s=>s.id===rec.left_survey_id)?.name||rec.left_survey_id}} / {{rec.left_group_id}} ↔ {{data.surveys.find(s=>s.id===rec.right_survey_id)?.name||rec.right_survey_id}} / {{rec.right_group_id}}</span><span v-if="rec.summary.checksum">SHA256 {{short(rec.summary.checksum)}}</span></div>
<p v-if="rec.status==='queued'||rec.status==='running'" role="status" class="notice">后台正在按字典序最优配对，完成后自动刷新；超过10秒将整份拒绝。</p>
<p v-if="rec.status==='failed'" role="alert" class="notice error">{{rec.error}} · 未保存任何部分结果，可调整阈值后新建对账。</p>
<template v-if="result"><div class="counts-strip"><span>候选配对<b>{{result.candidate_pair_count}}</b></span><span>最优对数<b>{{result.pair_count}}</b></span><span>必然配对<b>{{result.essential_pair_count}}</b></span><span>归属歧义<b>{{result.ambiguous_pair_count}}</b></span><span>左侧始终未配<b>{{result.left_counts.never_matched}}</b></span><span>右侧始终未配<b>{{result.right_counts.never_matched}}</b></span><span>总平方距离<b>{{num(result.total_squared_distance,6)}}</b> m²</span><span>耗时<b>{{result.timing_ms}}</b> ms</span></div>
<ReconcilePlot :result="result"/>
<div class="tabs"><button :class="{active:tab==='pairs'}" @click="tab='pairs'">配对台账</button><button :class="{active:tab==='left'}" @click="tab='left'">左侧点状态</button><button :class="{active:tab==='right'}" @click="tab='right'">右侧点状态</button><button :class="{active:tab==='notes'}" @click="tab='notes'">口径与来源</button></div>
<section v-if="tab==='pairs'" class="evidence-section"><h2>能出现在任一最优方案中的全部配对 / {{result.pairs.length}}对</h2><div class="table-scroll"><table><thead><tr><th>左侧编号</th><th>右侧编号</th><th>距离 / m</th><th>平方距离 / m²</th><th>分类</th><th>报告方案</th></tr></thead><tbody><tr v-for="p in shownPairs" :key="p.left_id+'='+p.right_id" :class="{critical:p.status==='ambiguous'}"><td>{{p.left_id}}</td><td>{{p.right_id}}</td><td>{{num(p.distance_m,6)}}</td><td>{{num(p.squared_distance,6)}}</td><td>{{PAIR_STATUSES[p.status]}}</td><td>{{p.in_reported?'在报告中':'备选'}}</td></tr></tbody></table></div><p v-if="result.pairs.length>shownPairs.length" class="muted">表格仅列前{{shownPairs.length}}对，全部{{result.pairs.length}}对保存在结果JSON与连线图中。</p></section>
<section v-else-if="tab==='left'" class="evidence-section"><h2>左侧点状态 / {{result.points.left.length}}条</h2><div class="table-scroll"><table><thead><tr><th>原始编号</th><th>x / m</th><th>y / m</th><th>状态</th><th>可配右侧编号</th></tr></thead><tbody><tr v-for="p in result.points.left" :key="p.point_id" :class="{critical:p.status==='never_matched'}"><td>{{p.point_id}}</td><td>{{num(p.x,8)}}</td><td>{{num(p.y,8)}}</td><td>{{MATCH_STATUSES[p.status]}}</td><td>{{p.partners.join('、')||'—'}}</td></tr></tbody></table></div></section>
<section v-else-if="tab==='right'" class="evidence-section"><h2>右侧点状态 / {{result.points.right.length}}条</h2><div class="table-scroll"><table><thead><tr><th>原始编号</th><th>x / m</th><th>y / m</th><th>状态</th><th>可配左侧编号</th></tr></thead><tbody><tr v-for="p in result.points.right" :key="p.point_id" :class="{critical:p.status==='never_matched'}"><td>{{p.point_id}}</td><td>{{num(p.x,8)}}</td><td>{{num(p.y,8)}}</td><td>{{MATCH_STATUSES[p.status]}}</td><td>{{p.partners.join('、')||'—'}}</td></tr></tbody></table></div></section>
<section v-else class="evidence-section"><h2>口径、来源与校验</h2><p>左侧来源：{{result.left.survey_name}} / {{result.left.group_id}} {{result.left.group_name}} / {{result.left.source}}；右侧来源：{{result.right.survey_name}} / {{result.right.group_id}} {{result.right.group_name}} / {{result.right.source}}。阈值{{result.threshold_m}}m已冻结进快照，对账不回写原始测组。</p><p v-for="s in result.assumptions" :key="s">{{s}}</p><p class="mono">{{result.checksum}}</p></section>
</template></article></template></template>
